"""H-27 step 4 final record (paper-eval/h26/h27-step4-census-v1.json) + register events. Inputs: lab/h27s4/h27-step4-draft.json
(aggregate), leak-candidates.json, manual-read.json (one verdict per LEAK_CANDIDATE production site: CONFIRMED | REFUTED with a
reason; the read can only refute), paper-eval/h26/h26b-census-v2.json (the corrected step-3 value). Frozen rules: cross-check
disagreement = EXPERIMENT_INVALID; v2 value < 20 = RECORD_AND_STOP (gate not evaluated); confirmed >= 10 ENGINE_EXPERIMENT (own
prereg) / 3-9 NARROW / < 3 KILL_STEP4."""
import json, datetime, subprocess, collections
S='/tmp/claude-0/-home-user/8a9da608-aa27-5449-8306-1fae9426f9b9/scratchpad'; P='/home/user/Own.NET-paperwork'; R='/home/user/Own.NET'
d=json.load(open(f'{S}/lab/h27s4/h27-step4-draft.json')); leak=json.load(open(f'{S}/lab/h27s4/leak-candidates.json')); mr=json.load(open(f'{S}/lab/h27s4/manual-read.json'))
v2=json.load(open(f'{P}/paper-eval/h26/h26b-census-v2.json')); value=v2['h27_step3_value']['count']
assert len(mr)==len(leak), (len(mr),len(leak)); assert all(m['verdict'] in ('CONFIRMED','REFUTED') for m in mr)
for m,l in zip(mr,leak): assert m['index']==leak.index(l) and m['file']==l['file'] and m['line']==l['line'], (m,l)
confirmed=[dict(l,reason=m['reason']) for m,l in zip(mr,leak) if m['verdict']=='CONFIRMED']; refuted=[dict(l,reason=m['reason']) for m,l in zip(mr,leak) if m['verdict']=='REFUTED']
invalid=d['cross_check']['verdict']!='OK' or not d['value_agreement']
if invalid: decision='EXPERIMENT_INVALID (harness: seam disagreement)'
elif value<20: decision=f'RECORD_AND_STOP (the corrected step-3 value {value} < 20: the step-3 rule governs, the step-4 gate is not evaluated)'
else: decision='ENGINE_EXPERIMENT (own prereg for the lowering and the OFF/ON scan)' if len(confirmed)>=10 else 'NARROW (the confirmed sites are the whole value of the effect; no engine work)' if len(confirmed)>=3 else 'KILL_STEP4 (no measurable value beyond using forms)'
own=subprocess.run(['git','rev-parse','HEAD'],cwd=R,capture_output=True,text=True).stdout.strip()
rec={'schema':'own.net/h27-step4/census/v1','written_at_utc':datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),'track':'H-27 step 4: owned-handle (lease) cheapest falsifier',
 'anchors':{'prereg':'paper-eval/h26/h27-step4-prereg-v1.json (f36f95f)','amendment_1':'paper-eval/h26/h27-step4-amendment-1.json (bbd5ac4)','erratum_4':'paper-eval/semantic-coverage/erratum-4-using-statement-declaration.json','seam_commit':'22908d2f (97 lines, census only)','own_net_head':own,'own_net_main':'fb06adc2beddd750e99a52ad8c1c8b5905602539 (untouched)','fixture':'corpus/ownership-lab/h27s4/fx/Lease.cs (29 methods, every class as intended)','step3_value_v2':'paper-eval/h26/h26b-census-v2.json'},
 'population':'the 8 frozen consumers, corrected environment, the H-25 unit row files, production units, TFM-collapsed per (consumer, file, line, callable); the same pass as the corrected H-26B census',
 'totals':{k:v for k,v in d.items() if k!='per_consumer'},'per_consumer':d['per_consumer'],
 'step3_value_corrected':{'count':value,'rule':'>= 20 keeps step 4 open (frozen)','ok':value>=20},
 'manual_read':{'sites_read':len(leak),'confirmed':len(confirmed),'refuted':len(refuted),'refutations_by_reason':dict(collections.Counter(m['reason'] for m in mr if m['verdict']=='REFUTED')),'confirmed_sites':confirmed,'refuted_sites':refuted},
 'gate':{'primary':len(confirmed),'rule':'confirmed LEAK_CANDIDATE production sites: >= 10 ENGINE_EXPERIMENT (own prereg) / 3-9 NARROW / < 3 KILL_STEP4 (frozen)','decision':decision},
 'descriptive_read_not_in_the_gate':{'rule':'the frozen manual read covers LEAK_CANDIDATE sites only (0 here); the three value sites that are not RELEASED / RECLAIMED were read for the record and enter no count',
   'sites':[{'site':'victor-wiki/DatabaseManager DbInterpreter.GetDataTableAsync (DbInterpreter.cs:699)','seam':'UNCLEAR: handle PASSED_TO_CALLEE (table.Load(reader)), receiver cmd is a local never released, the connection is a parameter (outlives the member)','reading':'a PLAUSIBLE true lease leak hidden by the argument pass: DataTable.Load consumes the first result set and leaves the reader open (it does not close it), the command is never disposed, and the caller-owned connection stays busy serving the reader (the ADO.NET protocol of P5 / P6); classifying it would need callee knowledge (a row saying DataTable.Load does not release its argument), which the step-4 seam does not have by design; NOT counted'},
     {'site':'JasperFx/weasel MultiCommandDataReader.OpenAsync (MultiCommandDataReader.cs:43)','seam':'UNCLEAR: handle PASSED_TO_CALLEE (new MultiCommandDataReader(commands, first)), receiver commands[0] outlives the member','reading':'an ownership transfer through a constructor argument (adoption): the wrapper stores the reader and disposes it in its own NextResultAsync / DisposeAsync; not a leak; the adoption shape is the H-23-family pattern already recorded in the hard-case taxonomy'},
     {'site':'JasperFx/wolverine PostgresqlQueueSender.ScheduleRetryAsync (PostgresqlQueueSender.cs:119)','seam':'RECLAIMED_IN_MEMBER: handle NONE, receiver conn is a local released by a using declaration and CloseAsync in finally; awaited = false','reading':'`var tx = conn.BeginTransactionAsync(cancellationToken);` is never awaited, never committed, never disposed: a dropped ValueTask<NpgsqlTransaction> (no compiler warning because the task is assigned); not a lease leak under the frozen rules (the receiver reclaims it on close), a different defect class (an un-awaited acquire); recorded, not counted'}]},
 'what_the_population_says':'of the 643 production sites of the frozen pair, 558 are using forms, 32 are released by an explicit call (Commit / Rollback / Dispose), 3 in a finally, 9 are transferred, 35 are non-local sinks, 5 are handed to a callee, 4 are reclaimed by a receiver released in the same member and 0 leave a lease unreleased with a receiver that outlives the member: on this population an owned-handle effect would report nothing that a using form or an explicit release does not already settle',
 'not_done':['no lowering','no vocabulary change','no engine change','H-26A']}
json.dump(rec,open(f'{P}/paper-eval/h26/h27-step4-census-v1.json','w'),indent=1); json.dump(rec,open(f'{S}/lab/h27s4/h27-step4-census-v1.json','w'),indent=1)
REG=f'{P}/paper-eval/ownership-lab/hypothesis-register-v1.json'; r=json.load(open(REG)); now=rec['written_at_utc']; t=v2['totals']; g=v2['gate']
ev=[{'at_utc':now,'hypothesis':'H-26B','event':'CENSUS_V2_RECORDED','summary':f"corrected seam (erratum 4), same pass as step 4: Q2b production {t['Q2b_production']}, frozen primary {g['primary']} = {g['share']}; sinks: {json.dumps(t['sink_distribution_production'],sort_keys=True)}",'decision':g['decision'],'record':'paper-eval/h26/h26b-census-v2.json'},
 {'at_utc':now,'hypothesis':'H-27','event':'VALUE_STEP3_RECOUNTED','summary':f"corrected frozen-pair value {value} ({v2['h27_step3_value']['count_wide_incl_sync']} with the synchronous twins); by callable {json.dumps(t['lease_families_frozen_pair']['value_by_callable'],sort_keys=True)}; by consumer {json.dumps(t['lease_families_frozen_pair']['value_by_consumer'],sort_keys=True)}",'decision':v2['h27_step3_value']['decision'],'record':'paper-eval/h26/h26b-census-v2.json'},
 {'at_utc':now,'hypothesis':'H-27','event':'STEP4_CENSUS_DONE','summary':f"frozen pair production sites {d['frozen_pair_production']}: classes {json.dumps(d['class_distribution_pair'],sort_keys=True)}; handle release {json.dumps(d['handle_release_pair'],sort_keys=True)}; receiver lifetime {json.dumps(d['receiver_lifetime_pair'],sort_keys=True)}; cross-check {d['cross_check']['shared_sites']} shared sites, {d['cross_check']['disagreements']} disagreements; LEAK_CANDIDATE {len(leak)} read by hand: {len(confirmed)} confirmed, {len(refuted)} refuted ({json.dumps(rec['manual_read']['refutations_by_reason'],sort_keys=True)})",'decision':decision,'record':'paper-eval/h26/h27-step4-census-v1.json'}]
have={(e.get('hypothesis'),e.get('event')) for e in r['log']}; new=[e for e in ev if (e['hypothesis'],e['event']) not in have]; r['log'].extend(new); json.dump(r,open(REG,'w'),indent=1)
print('register +%d'%len(new)); print('DECISION',decision,'| confirmed',len(confirmed),'refuted',len(refuted),'| value v2',value)
